<!doctype html><html lang="en"><head><meta charset="UTF-8"><title>Applications</title><link rel="stylesheet" href="/project/public/assets/css/style.css"></head><body><div class="container"><h2>Applications for Client Jobs</h2><?php if (!empty($_GET['success'])): ?><div class="alert alert-success">Application status updated.</div><?php endif; ?><?php if (!empty($_GET['error'])): ?><div class="alert alert-error">Invalid application status update.</div><?php endif; ?><form method="get" action="index.php"><input type="hidden" name="route" value="recruiter/applications"><div class="grid-2"><div><label>Job</label><select name="job_id"><option value="">All Jobs</option><?php foreach ($jobs as $job): ?><option value="<?php echo (int)$job['id']; ?>" <?php echo (string)$job['id'] === (string)($_GET['job_id'] ?? '') ? 'selected' : ''; ?>><?php echo htmlspecialchars($job['title']); ?></option><?php endforeach; ?></select></div><div><label>Status</label><select name="status"><option value="">All Status</option><?php foreach (['submitted','reviewed','shortlisted','interview','rejected','withdrawn','hired'] as $status): ?><option value="<?php echo $status; ?>" <?php echo (($_GET['status'] ?? '') === $status) ? 'selected' : ''; ?>><?php echo ucfirst($status); ?></option><?php endforeach; ?></select></div></div><div class="actions"><button type="submit">Filter</button><a class="btn btn-secondary" href="index.php?route=recruiter/dashboard">Back</a></div></form><div class="table-wrap"><table><tr><th>Seeker</th><th>Job</th><th>Client</th><th>Status</th><th>Applied At</th><th>Update</th></tr><?php foreach ($applications as $app): ?><tr><td><?php echo htmlspecialchars($app['seeker_name']); ?></td><td><?php echo htmlspecialchars($app['job_title']); ?></td><td><?php echo htmlspecialchars($app['client_name']); ?></td><td><?php echo htmlspecialchars($app['status']); ?></td><td><?php echo htmlspecialchars($app['applied_at']); ?></td><td><form method="post" action="index.php?route=recruiter/applications/status"><input type="hidden" name="application_id" value="<?php echo (int)$app['id']; ?>"><select name="status" required><?php foreach (['submitted','reviewed','shortlisted','interview','rejected','withdrawn','hired'] as $status): ?><option value="<?php echo $status; ?>" <?php echo $app['status'] === $status ? 'selected' : ''; ?>><?php echo ucfirst($status); ?></option><?php endforeach; ?></select><div class="actions"><button type="submit">Save</button></div></form></td></tr><?php endforeach; ?></table></div></div></body></html>
